/**
 * @distilled.cloud/mux -- Mux API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from Mux's OpenAPI document
 * (https://www.mux.com/api-spec.json), mirrored at
 * `specs/spec-mirror-mux/specs/api-spec.json`. Everything else in this folder
 * is hand-written.
 *
 * One module per API group, imported from its subpath: `video` (assets, live
 * streams, uploads, playback), `data` (views, metrics, monitoring),
 * `system` (signing keys, webhooks, usage) and `robots` (AI jobs).
 *
 * The image.mux.com and stream.mux.com playback URLs (thumbnails, HLS) are
 * not API calls and are not modeled.
 *
 * @example
 * ```ts
 * import * as Effect from "effect/Effect";
 * import * as Layer from "effect/Layer";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Mux from "@distilled.cloud/mux";
 * import * as System from "@distilled.cloud/mux/system";
 * import * as Video from "@distilled.cloud/mux/video";
 *
 * const program = Effect.gen(function* () {
 *   const { data: whoami } = yield* System.getWhoami({});
 *   const { data: assets } = yield* Video.listAssets({ limit: 5 });
 *   return { environment: whoami.environment_name, assets: assets.map((a) => a.id) };
 * });
 *
 * program.pipe(
 *   Effect.provide(Layer.mergeAll(FetchHttpClient.layer, Mux.CredentialsFromEnv)),
 *   Effect.runPromise,
 * );
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { MuxProtocol, type MuxOpError, type MuxOpContext } from "./protocol.ts";
export { paginatePage } from "./pagination.ts";
export * as Retry from "./retry.ts";
